      '<figure class="wp-block-image alignfull size-large"><a href="https://qrco.de/bbDYPo"><img data-attachment-id="156" data-permalink="https://tkmem.wordpress.com/dr_tamer_elalfy_social_media_links/" data-orig-file="https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png" data-orig-size="3000,3889" data-comments-opened="1" data-image-title="dr_tamer_elalfy_social_media_links" data-image-description="" data-image-caption="" data-large-file="https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=750" loading="lazy" width="3000" height="3889" src="https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png" alt="" class="wp-image-156" srcset="https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png 3000w, https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=116&amp;h=150 116w, https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=231&amp;h=300 231w, https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=768&amp;h=996 768w, https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=790&amp;h=1024 790w, https://tkmem.wordpress.com/wp-content/uploads/2019/08/dr_tamer_elalfy_social_media_links.png?w=1440&amp;h=1867 1440w" sizes="auto, (max-width: 3000px) 100vw, 3000px" /></a></figure>',
